from flask import Flask, request, redirect, url_for, render_template_string, session
from datetime import datetime
import csv
import io
import json
import os

app = Flask(__name__)
app.secret_key = os.environ.get('GAMMAJ_SECRET', 'dev-secret')

STATE = {
    'store': {'name': 'GAMMA-J Demo Store', 'currency': 'USD', 'setup_complete': False},
    'categories': ['General'],
    'products': [
        {'id': 1, 'name': 'Demo Tea', 'sku': 'TEA-001', 'barcode': '1001', 'category': 'General', 'price': 9.99, 'stock': 10, 'available': True, 'description': 'A simple starter product.', 'brand': 'Gamma', 'unit': 'box', 'variation': 'Standard'},
        {'id': 2, 'name': 'Demo Mug', 'sku': 'MUG-001', 'barcode': '1002', 'category': 'General', 'price': 12.5, 'stock': 5, 'available': True, 'description': 'A plain mug.', 'brand': 'Gamma', 'unit': 'each', 'variation': 'Large'},
    ],
    'customers': [{'id': 1, 'name': 'Alex Customer', 'email': 'alex@example.com', 'address': '1 Main St', 'consent': True}],
    'cart': [],
    'orders': [],
    'logs': [],
    'notifications': [],
    'issues': [],
    'imports': [],
    'manual_actions': [],
}

for o in STATE['orders']:
    pass


def now():
    return datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S UTC')


def add_log(entity, action, who='system', reason=''):
    STATE['logs'].append({'time': now(), 'entity': entity, 'action': action, 'who': who, 'reason': reason})


def notify(kind, message, severity='info'):
    STATE['notifications'].append({'time': now(), 'kind': kind, 'message': message, 'severity': severity})


def issue(title, detail, priority='medium'):
    STATE['issues'].append({'time': now(), 'title': title, 'detail': detail, 'priority': priority, 'resolved': False})


def find_product(pid):
    return next((p for p in STATE['products'] if p['id'] == pid), None)


def next_id(items):
    return max([i['id'] for i in items], default=0) + 1


def render_page(title, body):
    html = f"""
    <!doctype html>
    <html><head><meta charset='utf-8'><title>{title}</title>
    <style>
      body {{ font-family: Arial, sans-serif; margin: 20px; line-height: 1.4; }}
      nav a {{ margin-right: 12px; }}
      .card {{ border: 1px solid #ccc; padding: 12px; margin: 12px 0; border-radius: 8px; }}
      .small {{ color: #666; font-size: 0.92em; }}
      table {{ border-collapse: collapse; width: 100%; }}
      td, th {{ border: 1px solid #ddd; padding: 8px; vertical-align: top; }}
      .warn {{ background: #fff5cc; }} .bad {{ background: #ffe0e0; }} .ok {{ background: #e8ffe8; }}
      input, select, textarea {{ width: 100%; padding: 8px; margin: 4px 0 10px; box-sizing: border-box; }}
      .grid {{ display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }}
      .btn {{ display: inline-block; padding: 8px 12px; background: #2d6cdf; color: white; text-decoration: none; border: none; border-radius: 6px; cursor: pointer; }}
      .btn.secondary {{ background: #666; }}
      .btn.warn {{ background: #b26a00; }}
      .mono {{ font-family: monospace; }}
    </style></head><body>
    <nav>
      <a href='/'>Home</a><a href='/setup'>Setup</a><a href='/browse'>Browse</a><a href='/cart'>Cart</a><a href='/checkout'>Checkout</a><a href='/staff'>Staff</a><a href='/import'>Import</a><a href='/logs'>Logs</a><a href='/notifications'>Notifications</a>
    </nav>
    {body}
    </body></html>
    """
    return render_template_string(html)


@app.route('/')
def home():
    counts = {
        'products': len(STATE['products']), 'customers': len(STATE['customers']), 'orders': len(STATE['orders']),
        'issues': sum(1 for i in STATE['issues'] if not i['resolved'])
    }
    body = f"""
    <h1>GAMMA-J Web Store</h1>
    <p class='small'>Simple browser-based store for new sellers.</p>
    <div class='grid'>
      <div class='card'><strong>Store</strong><p>{STATE['store']['name']}</p><p>Setup complete: {'Yes' if STATE['store']['setup_complete'] else 'No'}</p></div>
      <div class='card'><strong>Summary</strong><p>Products: {counts['products']}</p><p>Customers: {counts['customers']}</p><p>Orders: {counts['orders']}</p><p>Unresolved issues: {counts['issues']}</p></div>
    </div>
    <div class='card'><strong>Plain-language tips</strong><p>Use Setup to add store details. Use Import for spreadsheet or CSV product uploads. Use Staff to manage products and orders.</p></div>
    """
    return render_page('Home', body)


@app.route('/setup', methods=['GET', 'POST'])
def setup():
    message = ''
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        currency = request.form.get('currency', 'USD').strip().upper()
        cats = [c.strip() for c in request.form.get('categories', '').split(',') if c.strip()]
        if not name:
            message = 'Please enter a store name. This is needed before you start selling.'
        else:
            STATE['store'].update({'name': name, 'currency': currency, 'setup_complete': True})
            if cats:
                STATE['categories'] = sorted(set(STATE['categories'] + cats))
            add_log('store', 'setup updated')
            notify('setup', 'Store setup saved.', 'info')
            return redirect(url_for('home'))
    body = f"""
    <h1>Guided setup</h1>
    <div class='card'>
      <p><strong>Step 1:</strong> Enter basic store information.</p>
      <p><strong>Step 2:</strong> Add categories, products, and customer account settings.</p>
      <p><strong>Step 3:</strong> Review clear examples and prompts before you begin selling.</p>
      <form method='post'>
        <label>Store name</label><input name='name' value='{STATE['store']['name']}' placeholder='Example Store'>
        <label>Currency</label><input name='currency' value='{STATE['store']['currency']}' placeholder='USD'>
        <label>Categories separated by commas</label><input name='categories' placeholder='Shoes, Accessories'>
        <button class='btn' type='submit'>Save setup</button>
      </form>
      <p class='small'>{message}</p>
    </div>
    """
    return render_page('Setup', body)


@app.route('/browse')
def browse():
    rows = ''.join(f"<tr><td>{p['name']}</td><td>{p['category']}</td><td>{p['price']}</td><td>{p['stock']}</td><td><a class='btn' href='/cart/add/{p['id']}'>Add to cart</a></td></tr>" for p in STATE['products'])
    return render_page('Browse', f"<h1>Browse products</h1><table><tr><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th></th></tr>{rows}</table>")


@app.route('/cart')
def cart():
    total = 0
    rows = ''
    for item in STATE['cart']:
        p = find_product(item['product_id'])
        subtotal = item['qty'] * p['price']
        total += subtotal
        rows += f"<tr><td>{p['name']}</td><td>{item['qty']}</td><td>{subtotal:.2f}</td><td><a class='btn secondary' href='/cart/remove/{p['id']}'>Remove</a></td></tr>"
    return render_page('Cart', f"<h1>Shopping cart</h1><table><tr><th>Product</th><th>Qty</th><th>Subtotal</th><th></th></tr>{rows}</table><p><strong>Total:</strong> {total:.2f}</p>")


@app.route('/cart/add/<int:pid>')
def cart_add(pid):
    found = next((x for x in STATE['cart'] if x['product_id'] == pid), None)
    if found:
        found['qty'] += 1
    else:
        STATE['cart'].append({'product_id': pid, 'qty': 1})
    add_log('cart', f'add product {pid}')
    return redirect(url_for('cart'))


@app.route('/cart/remove/<int:pid>')
def cart_remove(pid):
    STATE['cart'] = [x for x in STATE['cart'] if x['product_id'] != pid]
    add_log('cart', f'remove product {pid}')
    return redirect(url_for('cart'))


@app.route('/checkout', methods=['GET', 'POST'])
def checkout():
    errors = []
    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        address = request.form.get('address', '').strip()
        payment = request.form.get('payment', '').strip()
        shipping = request.form.get('shipping', '').strip()
        if not name: errors.append('Customer name is required.')
        if not email or '@' not in email: errors.append('Please enter a valid email address.')
        if not address: errors.append('Shipping address is required.')
        if payment.lower() not in ['card', 'paypal', 'gateway']:
            errors.append('Payment details look incomplete or invalid.')
        if not shipping: errors.append('Shipping method is required.')
        if errors:
            body = "<h1>Checkout</h1><div class='card bad'><strong>Please correct these items:</strong><ul>" + ''.join(f'<li>{e}</li>' for e in errors) + "</ul><p>You stay on this page while fixing the form.</p></div>" + checkout_form()
            return render_page('Checkout', body)
        if not STATE['cart']:
            return render_page('Checkout', "<h1>Checkout</h1><p>Your cart is empty.</p>")
        order = {'id': next_id(STATE['orders']), 'customer': name, 'email': email, 'address': address, 'payment_status': 'unpaid', 'shipping_status': 'pending', 'items': list(STATE['cart']), 'created': now()}
        STATE['orders'].append(order)
        STATE['cart'] = []
        issue('Payment failure possible', f'Order {order["id"]} awaiting payment confirmation', 'high')
        notify('order', f'Order {order["id"]} placed. Payment may need attention.', 'warning')
        add_log('order', f'create order {order["id"]}', who=name)
        return render_page('Checkout', f"<h1>Order placed</h1><p>Order #{order['id']} saved. Payment status: unpaid for staff visibility.</p>")
    return render_page('Checkout', "<h1>Checkout</h1>" + checkout_form())


def checkout_form():
    return """
    <div class='card'>
      <p><strong>Validation happens before submission.</strong> Required customer, shipping, and payment information must be present.</p>
      <form method='post'>
        <label>Name</label><input name='name'>
        <label>Email</label><input name='email'>
        <label>Address</label><input name='address'>
        <label>Payment method</label><input name='payment' placeholder='card'>
        <label>Shipping method</label><input name='shipping' placeholder='standard'>
        <button class='btn' type='submit'>Place order</button>
      </form>
    </div>
    """


@app.route('/staff')
def staff():
    unresolved = [i for i in STATE['issues'] if not i['resolved']]
    products = ''.join(f"<tr><td>{p['id']}</td><td>{p['name']}</td><td>{p['available']}</td><td>{p['stock']}</td><td><a class='btn secondary' href='/staff/toggle/{p['id']}'>Toggle availability</a></td></tr>" for p in STATE['products'])
    orders = ''.join(f"<tr><td>{o['id']}</td><td>{o['customer']}</td><td>{o['payment_status']}</td><td>{o['shipping_status']}</td><td><a class='btn' href='/staff/pay/{o['id']}'>Retry payment</a> <a class='btn warn' href='/staff/ship/{o['id']}'>Retry shipping</a></td></tr>" for o in STATE['orders'])
    issues = ''.join(f"<li>{i['priority']} - {i['title']}: {i['detail']}</li>" for i in unresolved) or '<li>No unresolved issues.</li>'
    return render_page('Staff', f"<h1>Staff dashboard</h1><p>Payment failures are highest priority.</p><div class='card'><strong>Unresolved issues</strong><ul>{issues}</ul></div><table><tr><th>ID</th><th>Product</th><th>Available</th><th>Stock</th><th></th></tr>{products}</table><h2>Orders</h2><table><tr><th>ID</th><th>Customer</th><th>Payment</th><th>Shipping</th><th></th></tr>{orders}</table>")


@app.route('/staff/toggle/<int:pid>')
def toggle_product(pid):
    p = find_product(pid)
    if p:
        p['available'] = not p['available']
        add_log('product', f'toggle availability {pid}', who='staff')
        notify('stock', f'Product {p["name"]} availability changed.', 'info')
    return redirect(url_for('staff'))


@app.route('/staff/pay/<int:oid>')
def pay_order(oid):
    o = next((x for x in STATE['orders'] if x['id'] == oid), None)
    if o:
        o['payment_status'] = 'paid'
        add_log('order', f'payment resolved {oid}', who='staff', reason='manual retry')
        STATE['manual_actions'].append({'time': now(), 'staff': 'staff', 'reason': 'manual retry', 'original_error': 'payment failure', 'action': 'payment retry', 'order_id': oid})
    return redirect(url_for('staff'))


@app.route('/staff/ship/<int:oid>')
def ship_order(oid):
    o = next((x for x in STATE['orders'] if x['id'] == oid), None)
    if o:
        o['shipping_status'] = 'shipped'
        add_log('order', f'shipping resolved {oid}', who='staff', reason='manual retry')
    return redirect(url_for('staff'))


@app.route('/import', methods=['GET', 'POST'])
def import_data():
    summary = ''
    if request.method == 'POST':
        data = request.form.get('csvdata', '').strip()
        fp = io.StringIO(data)
        reader = csv.DictReader(fp)
        imported = skipped = issues_count = 0
        rows = []
        for row in reader:
            name = (row.get('name') or '').strip()
            sku = (row.get('sku') or '').strip()
            barcode = (row.get('barcode') or '').strip()
            price = row.get('price', '').strip()
            category = (row.get('category') or 'General').strip() or 'General'
            duplicate = any((sku and p['sku'] == sku) or (barcode and p['barcode'] == barcode) or (name and p['name'].lower() == name.lower()) for p in STATE['products'])
            issue_text = []
            if not name: issue_text.append('Missing product name')
            if not price or not str(price).replace('.', '', 1).isdigit(): issue_text.append('Missing or invalid price')
            if duplicate: issue_text.append('Possible duplicate')
            rows.append((row, issue_text))
            if issue_text:
                issues_count += 1
                skipped += 1
            else:
                STATE['products'].append({'id': next_id(STATE['products']), 'name': name, 'sku': sku or f'SKU-{next_id(STATE["products"])}', 'barcode': barcode or '', 'category': category, 'price': float(price), 'stock': int(row.get('stock', 0) or 0), 'available': True, 'description': row.get('description', ''), 'brand': row.get('brand', ''), 'unit': row.get('unit', ''), 'variation': row.get('variation', '')})
                imported += 1
        STATE['imports'].append({'time': now(), 'imported': imported, 'skipped': skipped, 'issues': issues_count})
        summary = f"<div class='card ok'><strong>Import complete</strong><p>Succeeded: {imported}</p><p>Skipped: {skipped}</p><p>Needs attention: {issues_count}</p></div>"
    body = summary + """
    <h1>Product import</h1>
    <div class='card'>
      <p>Paste CSV data below. The wizard is intentionally small and step-by-step.</p>
      <p class='small'>Required columns: name, sku, barcode, category, price, stock. Suggestions are shown for review only; no silent changes are made.</p>
      <form method='post'>
        <textarea name='csvdata' rows='12' placeholder='name,sku,barcode,category,price,stock\nDemo Pen,PEN-1,2001,Office,2.5,20'></textarea>
        <button class='btn' type='submit'>Import CSV</button>
      </form>
    </div>
    """
    return render_page('Import', body)


@app.route('/logs')
def logs():
    items = ''.join(f"<li><span class='mono'>{l['time']}</span> | {l['entity']} | {l['action']} | {l['who']} {('(' + l['reason'] + ')') if l['reason'] else ''}</li>" for l in reversed(STATE['logs'])) or '<li>No logs yet.</li>'
    return render_page('Logs', f"<h1>Change log</h1><p>Shows who changed orders or products and when.</p><ul>{items}</ul>")


@app.route('/notifications')
def notifications():
    items = ''.join(f"<li><strong>{n['severity']}</strong> [{n['kind']}] {n['message']} - {n['time']}</li>" for n in reversed(STATE['notifications'])) or '<li>No notifications yet.</li>'
    return render_page('Notifications', f"<h1>Notifications</h1><p>In-app alerts for important updates.</p><ul>{items}</ul>")


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '8000')), debug=False)
EOF

